import FeatureSectionV2 from "./feature-section-v2"

export default function Page() {
  return <FeatureSectionV2 />
}

export type Feature = {
  id: string
  title: string
  description: string
}

export const features: Feature[] = [
  {
    id: "workflow-automation",
    title: "Workflow automation",
    description:
      "Set it up once and let it run. Your team gets back the time that used to disappear into repetitive work.",
  },
  {
    id: "real-time-analytics",
    title: "Real-time analytics",
    description:
      "Pull live data into your dashboards so you can act on it while it still matters, not days later when the weekly export finally lands.",
  },
  {
    id: "access-control",
    title: "Access control",
    description:
      "Give people exactly the access they need, keep sensitive areas locked down, and put an end to the permission requests piling up in your inbox.",
  },
  {
    id: "integrations",
    title: "Integrations",
    description:
      "Connect the tools your team already uses in minutes, without turning it into another engineering project.",
  },
]

/* feature-section-v2 */

.fsv2-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

@media (min-width: 640px) {
  .fsv2-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.fsv2-cell {
  min-width: 0;
}

/* ── Card ── */

.fsv2-card {
  position: relative;
  /* Fixed preview height — real-time analytics card is the reference for all four */
  --fsv2-illustration-height: 12rem;
  min-height: 17rem;
  background-color: color-mix(in oklab, var(--muted) 82%, var(--background) 18%);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
}

@media (max-width: 639px) {
  .fsv2-card {
    --fsv2-illustration-height: 10.5rem;
  }
}

.fsv2-card-top {
  flex: 0 0 var(--fsv2-illustration-height);
  height: var(--fsv2-illustration-height);
  min-height: var(--fsv2-illustration-height);
  max-height: var(--fsv2-illustration-height);
  display: flex;
  flex-direction: column;
}

/* Illustration fills the preview pane edge-to-edge and uses available height */
.fsv2-card-top > * {
  flex: 1 1 0%;
  min-height: 0;
  min-width: 0;
  align-self: stretch;
  width: 100%;
}

.fsv2-card-footer {
  margin-top: auto;
  padding: 1rem 1.1rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.fsv2-card-title {
  margin: 0;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  line-height: 1.35;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--foreground) 88%, transparent);
}

.fsv2-card-desc {
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: var(--muted-foreground);
  /* Keeps card footers aligned when copy wraps across breakpoints */
  min-height: calc(0.8125rem * 1.55 * 3);
}

/* ── Caret blink (type-on, per SKILL § 5 · Caret) ── */
/* Used by access-control email field and integrations search input */

@keyframes fsv2-caret-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

.fsv2-caret {
  animation: fsv2-caret-blink 1s steps(2) infinite;
}

@media (prefers-reduced-motion: reduce) {
  .fsv2-caret {
    animation: none;
  }
}

/* ── Row appear (integrations stagger reveal, per SKILL § 5 · Stagger) ── */

@keyframes fsv2-row-appear {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fsv2-row-appear {
  animation: fsv2-row-appear 0.18s ease-out both;
}

@media (prefers-reduced-motion: reduce) {
  .fsv2-row-appear {
    animation: none;
  }
}

"use client"

import { MousePointer2 } from "lucide-react"

import { cn } from "@/lib/utils"

/**
 * Shared cursor primitive (per `.claude/skills/illustrations/SKILL.md` § 5 · Cursor canvas).
 * Positioned with percentages so it follows the card body's layout without magic pixel values.
 *
 * Theme compatibility: the arrow is `fill-foreground` (dark in light mode, light in dark mode)
 * and gets a `stroke-background` outline (2px) so it stays readable on `bg-card`, `bg-muted`
 * hover rows, and any accent chip beneath it — no hard-coded black/white.
 */
type CursorProps = {
  /** 0–100, as a percentage of the cursor canvas */
  x: number
  y: number
  /** `true` while the phase is a click — scales the cursor down briefly */
  pressed?: boolean
  className?: string
}

export function Cursor({ x, y, pressed, className }: CursorProps) {
  return (
    <MousePointer2
      aria-hidden
      strokeWidth={2}
      className={cn(
        "pointer-events-none absolute z-10 size-3.5",
        "fill-foreground stroke-background text-foreground",
        "[paint-order:stroke_fill]",
        "motion-safe:transition-[left,top,transform] motion-safe:duration-500 motion-safe:ease-out",
        className,
      )}
      style={{
        left: `${x}%`,
        top: `${y}%`,
        transform: `translate(-2px, -2px)${pressed ? " scale(0.92)" : ""}`,
      }}
    />
  )
}

"use client"

/**
 * Product surface: Automation run detail — queued steps resolve into a finished run.
 * Body: compact run table (Step · Status · Duration); run id + status live in the footer.
 * Accent (one element): green `~12 min` in the footer when the run completes.
 * No cursor — read-only run viewer.
 */

import { ChevronDown, Loader, Play, RotateCw } from "lucide-react"
import { useEffect, useState } from "react"

import { cn } from "@/lib/utils"

import { useFsv2IllustrationActive } from "../hooks/use-fsv2-illustration-active"
import {
  useWorkflowAnimation,
  WORKFLOW_STEPS,
  RETRY_STEP_IDX,
} from "../hooks/use-workflow-animation"

export default function WorkflowIllustration() {
  const active = useFsv2IllustrationActive()
  const [playing, setPlaying] = useState(false)
  const { lineIdx, isResult, phase, retryState } = useWorkflowAnimation(playing)

  useEffect(() => {
    if (!active || playing) return
    const t = setTimeout(() => setPlaying(true), 800)
    return () => clearTimeout(t)
  }, [active, playing])

  useEffect(() => {
    if (phase === "resetting") setPlaying(false)
  }, [phase])

  return (
    <div className="flex size-full flex-col overflow-hidden rounded-lg border border-border bg-card">
      <div className="flex min-h-0 flex-1 flex-col px-2.5 pt-2.5">
        <div className="flex min-h-0 flex-1 flex-col gap-0.5">
          {WORKFLOW_STEPS.map((step, i) => {
            const isRetryStep = i === RETRY_STEP_IDX
            const failed    = isRetryStep && retryState === "failed"
            const retrying  = isRetryStep && retryState === "retrying"
            const done      = isResult || (i < lineIdx && !(failed || retrying))
            const running   = !isResult && i === lineIdx && !failed && !retrying
            const pending   = !done && !running && !failed && !retrying
            const showArrow = i < WORKFLOW_STEPS.length - 1

            return (
              <div key={step.id}>
                <div
                  className={cn(
                    "grid grid-cols-[minmax(0,1fr)_4.5rem_2.75rem] items-center gap-x-1.5 rounded-sm px-1 py-0.5 text-[10.5px] leading-tight transition-colors duration-200",
                    (running || failed || retrying) && "bg-muted/60",
                    done && "bg-muted/25",
                  )}
                >
                  <span
                    className={cn(
                      "min-w-0 truncate",
                      pending ? "text-muted-foreground/70" : "text-foreground",
                    )}
                  >
                    {step.label}
                  </span>
                  <span className="flex justify-end">
                    {failed ? (
                      <span className="text-[10px] font-medium text-red-500">Failed</span>
                    ) : retrying ? (
                      <span className="inline-flex items-center justify-end gap-1 text-amber-500">
                        <RotateCw className="size-2.5 shrink-0 motion-safe:animate-spin" aria-hidden />
                        <span className="text-[10px] font-medium">Retrying</span>
                      </span>
                    ) : running ? (
                      <span className={cn("inline-flex items-center justify-end", step.runColor)}>
                        <RotateCw className="size-2.5 shrink-0 motion-safe:animate-spin" aria-hidden />
                      </span>
                    ) : done ? (
                      <span className="text-[10px] font-medium text-emerald-500">Done</span>
                    ) : (
                      <span className="text-[10px] text-muted-foreground/40">—</span>
                    )}
                  </span>
                  <span
                    className={cn(
                      "text-right font-mono tabular-nums text-[10px]",
                      done     ? step.msColor
                      : failed ? "text-red-500/60"
                      : retrying ? "text-amber-500/60"
                      : running  ? "text-muted-foreground/50"
                      : "text-muted-foreground/30",
                    )}
                  >
                    {done ? step.ms : (running || retrying) ? "…" : "—"}
                  </span>
                </div>
                {showArrow && (
                  <div className="flex justify-center py-0.5" aria-hidden>
                    <ChevronDown className="size-2.5 text-muted-foreground/40" />
                  </div>
                )}
              </div>
            )
          })}
        </div>
      </div>

      <div className="grid h-6 shrink-0 grid-cols-3 items-center border-t border-border px-2.5 text-[10px]">
        <span className="font-mono tabular-nums text-muted-foreground">Run #482</span>
        <span className="flex items-center justify-center gap-1">
          {!playing && !isResult ? (
            <button
              type="button"
              onClick={() => setPlaying(true)}
              className="inline-flex items-center justify-center rounded-full p-0.5 text-muted-foreground transition-colors hover:text-foreground"
              aria-label="Run workflow"
            >
              <Play className="size-3 fill-current" aria-hidden />
            </button>
          ) : isResult ? (
            <span className="text-foreground">All steps completed</span>
          ) : (
            <>
              <Loader className="size-3 shrink-0 text-muted-foreground motion-safe:animate-spin" aria-hidden />
              <span className="text-muted-foreground">Executing steps</span>
            </>
          )}
        </span>
        <span className="flex items-center justify-end gap-1">
          {isResult ? (
            <>
              <span className="text-muted-foreground">Total</span>
              <span className="font-mono tabular-nums text-green-500">~12 min</span>
            </>
          ) : (
            <span className="text-muted-foreground/40">—</span>
          )}
        </span>
      </div>
    </div>
  )
}

"use client"

import { TrendingUp } from "lucide-react"
import { Area, AreaChart, CartesianGrid, XAxis, YAxis } from "recharts"

import {
  ChartContainer,
  type ChartConfig,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart"

import { useFsv2IllustrationActive } from "../hooks/use-fsv2-illustration-active"
import { useAnalyticsAnimation } from "../hooks/use-analytics-animation"

export default function AnalyticsIllustration() {
  const active = useFsv2IllustrationActive()
  const { phase, view, users, config, isResult } = useAnalyticsAnimation(active)
  const showChart = phase === "acting" || phase === "result" || phase === "holding"

  const chartConfig = {
    v: { label: "Sessions", color: config.color },
  } satisfies ChartConfig

  return (
    <div className="flex size-full flex-col overflow-hidden rounded-lg border border-border bg-card px-2.5 pt-2.5 pb-2">
      <div className="mb-1.5 flex shrink-0 items-baseline gap-2">
        <span className="font-mono text-[18px] font-semibold leading-none tabular-nums text-foreground">
          {users.toLocaleString()}
        </span>
        {isResult && (
          <span className="inline-flex items-center gap-0.5 rounded-sm bg-muted px-1 py-px text-[10px] font-medium tabular-nums text-foreground">
            <TrendingUp className="size-2.5" aria-hidden />
            {config.trend}
          </span>
        )}
        <span className="ml-auto text-[10px] text-muted-foreground">{config.label}</span>
      </div>

      <ChartContainer
        id="fsv2-analytics"
        key={view}
        config={chartConfig}
        className="aspect-auto size-full"
      >
        <AreaChart
          data={config.series as unknown as Array<{ day: string; v: number }>}
          margin={{ top: 4, right: 8, left: 8, bottom: 4 }}
        >
          <defs>
            <linearGradient id="fsv2-analytics-fill" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--color-v)" stopOpacity={0.25} />
              <stop offset="100%" stopColor="var(--color-v)" stopOpacity={0.02} />
            </linearGradient>
          </defs>
          <CartesianGrid
            vertical={false}
            strokeDasharray="2 4"
            className="stroke-border/70"
          />
          <XAxis
            dataKey="day"
            tickLine={false}
            axisLine={false}
            tickMargin={4}
            height={14}
            padding={{ left: 6, right: 6 }}
            tick={{ fontSize: 9, fill: "currentColor" }}
            className="fill-muted-foreground text-muted-foreground"
            interval={0}
          />
          <YAxis hide domain={["dataMin - 1500", "dataMax + 500"]} />
          <ChartTooltip
            cursor={false}
            content={
              <ChartTooltipContent
                hideLabel
                labelClassName="text-[10px]"
                className="px-2 py-1 text-[10px]"
              />
            }
          />
          {showChart && (
            <Area
              dataKey="v"
              type="monotone"
              stroke="var(--color-v)"
              strokeWidth={1.5}
              fill="url(#fsv2-analytics-fill)"
              isAnimationActive
              animationDuration={700}
              animationEasing="ease-out"
              dot={false}
              activeDot={{ r: 2.5 }}
            />
          )}
        </AreaChart>
      </ChartContainer>
    </div>
  )
}

"use client"

import { ChevronRight, CornerDownLeft, Loader2, Search } from "lucide-react"

import { cn } from "@/lib/utils"
import { GithubDark } from "@/components/ui/svgs/githubDark"
import { GithubLight } from "@/components/ui/svgs/githubLight"
import { Openai } from "@/components/ui/svgs/openai"
import { OpenaiDark } from "@/components/ui/svgs/openaiDark"
import { Supabase } from "@/components/ui/svgs/supabase"
import { Vercel } from "@/components/ui/svgs/vercel"
import { VercelDark } from "@/components/ui/svgs/vercelDark"

import { useFsv2IllustrationActive } from "../hooks/use-fsv2-illustration-active"
import {
  INTEGRATIONS,
  INTEGRATIONS_TARGET_IDX,
  useIntegrationsAnimation,
} from "../hooks/use-integrations-animation"
import { Cursor } from "./cursor"

import type { Integration } from "../hooks/use-integrations-animation"

/** `*Dark` SVGs use white fills — invisible on light `bg-card`. Pair with default/Light variants. */
function IntegrationBrandMark({ id }: { id: Integration["id"] }) {
  switch (id) {
    case "github":
      return (
        <>
          <GithubLight className="size-3.5 shrink-0 dark:hidden" aria-hidden />
          <GithubDark className="size-3.5 shrink-0 hidden dark:block" aria-hidden />
        </>
      )
    case "vercel":
      return (
        <>
          <Vercel className="size-3.5 shrink-0 dark:hidden" aria-hidden />
          <VercelDark className="size-3.5 shrink-0 hidden dark:block" aria-hidden />
        </>
      )
    case "supabase":
      return <Supabase className="size-3.5 shrink-0" aria-hidden />
    case "openai":
      return (
        <>
          <Openai className="size-3.5 shrink-0 dark:hidden" aria-hidden />
          <OpenaiDark className="size-3.5 shrink-0 hidden dark:block" aria-hidden />
        </>
      )
    default:
      return null
  }
}

/**
 * Cursor y-center for a given row.
 * Body has py-1 (≈3% of body height) and rows are h-[22%] each —
 * so row `idx` center sits at 3 + idx*22 + 11 % of the body div.
 */
function cursorY(idx: number) {
  return 3 + idx * 22 + 11
}

export default function IntegrationsIllustration() {
  const active = useFsv2IllustrationActive()
  const { hoverIdx, query, pressed, visibleCount, isResult, cursorOnConnect, isLoading } =
    useIntegrationsAnimation(active)

  const effectiveHover = isResult ? INTEGRATIONS_TARGET_IDX : hoverIdx

  // Cursor position:
  // - idle (no hover): bottom-left corner of the body (palette just opened)
  // - hovering rows: x=86 (over the chevron area on the right side)
  // - on Connect button: x=90 (centered on the purple chip; chip spans ~86–97% at max-w-6xl grid width)
  const cursor =
    effectiveHover < 0
      ? { x: 8, y: 96 }
      : { x: cursorOnConnect ? 90 : 86, y: cursorY(effectiveHover) }

  return (
    <div className="flex size-full flex-col overflow-hidden rounded-lg border border-border bg-card">
      {/* Top bar = the palette's search input */}
      <header className="flex h-7 shrink-0 items-center gap-1.5 border-b border-border px-2.5">
        <Search className="size-3 shrink-0 text-muted-foreground" aria-hidden />
        <span
          className={cn(
            "min-w-0 flex-1 truncate font-mono text-[11px]",
            query ? "text-foreground" : "text-muted-foreground/70",
          )}
        >
          {query || "Connect an integration…"}
          <span className="ml-0.5 inline-block h-2.5 w-px align-middle bg-foreground/70 fsv2-caret" />
        </span>
        <kbd className="inline-flex h-4 shrink-0 items-center rounded-sm border border-border bg-muted px-1 font-mono text-[9px] font-medium text-muted-foreground">
          ⌘K
        </kbd>
      </header>

      {/* Body — results list (relative, acts as cursor canvas) */}
      <div className="relative flex min-h-0 flex-1 flex-col py-1">
        {INTEGRATIONS.slice(0, visibleCount).map((item, i) => {
          const hovered = effectiveHover === i
          const target = i === INTEGRATIONS_TARGET_IDX && isResult

          return (
            <div
              key={item.id}
              className={cn(
                "flex h-[22%] items-center gap-2 border-l-2 px-2.5 text-[11px] transition-colors fsv2-row-appear",
                hovered
                  ? "border-foreground/40 bg-muted/60"
                  : "border-transparent",
              )}
            >
              <IntegrationBrandMark id={item.id} />
              <span className="min-w-0 truncate font-medium text-foreground">
                {item.name}
              </span>
              <span className="truncate text-[10px] text-muted-foreground">
                {item.kind}
              </span>

              {target ? (
                <span
                  className={cn(
                    "ml-auto inline-flex h-4 items-center gap-1 rounded-sm px-1.5 text-[10px] font-medium text-purple-500",
                    "transition-[transform,background-color] duration-75",
                    pressed
                      ? "scale-[0.91] bg-purple-500/25"
                      : isLoading
                        ? "bg-purple-500/15"
                        : "bg-purple-500/10",
                  )}
                >
                  {isLoading ? (
                    <Loader2 className="size-2.5 animate-spin" aria-hidden />
                  ) : (
                    <>
                      Connect
                      <ChevronRight className="size-2.5" aria-hidden />
                    </>
                  )}
                </span>
              ) : hovered ? (
                <ChevronRight
                  className="ml-auto size-3 shrink-0 text-muted-foreground"
                  aria-hidden
                />
              ) : (
                <span className="ml-auto w-4 shrink-0" aria-hidden />
              )}
            </div>
          )
        })}

        <Cursor x={cursor.x} y={cursor.y} pressed={pressed} />
      </div>

      {/* Footer — keyboard hints */}
      <div className="flex h-6 shrink-0 items-center gap-2 border-t border-border px-2.5 text-[9px] text-muted-foreground">
        <span className="inline-flex items-center gap-1">
          <kbd className="inline-flex h-3.5 items-center gap-0.5 rounded-sm border border-border bg-muted px-1 font-mono text-[8px]">
            <span>↑</span><span>↓</span>
          </kbd>
          <span>Navigate</span>
        </span>
        <span className="inline-flex items-center gap-1">
          <kbd className="inline-flex h-3.5 items-center rounded-sm border border-border bg-muted px-1 font-mono text-[8px]">
            <CornerDownLeft className="size-2.5" aria-hidden />
          </kbd>
          <span>Connect</span>
        </span>
        <span className="ml-auto tabular-nums">
          {INTEGRATIONS.length} sources
        </span>
      </div>
    </div>
  )
}

"use client"

import {
  createContext,
  createElement,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react"

const Fsv2IllustrationActiveContext = createContext(true)

/**
 * Single IntersectionObserver for the whole feature grid — timers pause when the block is off-screen.
 * Attach `ref` to the block’s `<ul>` from `components/feature-showcase.tsx`.
 */
export function useFsv2IllustrationBlockGate() {
  const ref = useRef<HTMLUListElement>(null)
  const [active, setActive] = useState(true)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    const obs = new IntersectionObserver(
      ([e]) => setActive(!!e?.isIntersecting),
      { rootMargin: "48px", threshold: 0.12 },
    )
    obs.observe(el)
    return () => obs.disconnect()
  }, [])

  return { ref, active }
}

export function Fsv2IllustrationActiveProvider({
  active,
  children,
}: {
  active: boolean
  children: ReactNode
}) {
  return createElement(
    Fsv2IllustrationActiveContext.Provider,
    { value: active },
    children,
  )
}

/** Active flag from {@link Fsv2IllustrationActiveProvider} (one gate per block). */
export function useFsv2IllustrationActive() {
  return useContext(Fsv2IllustrationActiveContext)
}

export function useFsv2ReducedMotion() {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    const sync = () => setReduced(mq.matches)
    sync()
    mq.addEventListener("change", sync)
    return () => mq.removeEventListener("change", sync)
  }, [])

  return reduced
}

"use client"

import { useEffect, useState } from "react"

export type WorkflowPhase =
  | "setup"
  | "acting"
  | "result"
  | "holding"
  | "resetting"

export type RetryState = "failed" | "retrying" | null

const TIMING: Record<WorkflowPhase, number> = {
  setup:     500,
  acting:    3600,
  result:    300,
  holding:   3000,
  resetting: 320,
}

const STEP_MS   = 520
const RETRY_IDX = 2

export type WorkflowStep = {
  id: string
  label: string
  ms: string
  runColor: string
  msColor: string
}

export const WORKFLOW_STEPS: readonly WorkflowStep[] = [
  { id: "signup",    label: "User signed up",     ms: "61ms",  runColor: "text-sky-500",    msColor: "text-emerald-500" },
  { id: "email",     label: "Verify email",        ms: "18ms",  runColor: "text-amber-500",  msColor: "text-emerald-500" },
  { id: "workspace", label: "Provision workspace", ms: "820ms", runColor: "text-violet-500", msColor: "text-red-500"     },
  { id: "welcome",   label: "Send welcome",        ms: "290ms", runColor: "text-rose-500",   msColor: "text-amber-500"   },
]

export const RETRY_STEP_IDX = RETRY_IDX

export function useWorkflowAnimation(active: boolean) {
  const [phase, setPhase]           = useState<WorkflowPhase>("setup")
  const [lineIdx, setLineIdx]       = useState(0)
  const [retryState, setRetryState] = useState<RetryState>(null)

  useEffect(() => {
    if (!active) {
      setPhase("setup")
      setLineIdx(0)
      setRetryState(null)
      return
    }

    const next: Record<WorkflowPhase, WorkflowPhase> = {
      setup: "acting", acting: "result", result: "holding",
      holding: "resetting", resetting: "setup",
    }

    const t = setTimeout(() => setPhase(next[phase]), TIMING[phase])
    return () => clearTimeout(t)
  }, [active, phase])

  useEffect(() => {
    if (!active) return

    if (phase === "setup" || phase === "resetting") {
      setLineIdx(0)
      setRetryState(null)
      return
    }
    if (phase === "result" || phase === "holding") {
      setLineIdx(WORKFLOW_STEPS.length)
      setRetryState(null)
      return
    }
    if (phase !== "acting") return

    const timers: ReturnType<typeof setTimeout>[] = []
    setLineIdx(0)
    setRetryState(null)

    // Steps before the retry step
    for (let i = 1; i <= RETRY_IDX; i++) {
      timers.push(setTimeout(() => setLineIdx(i), STEP_MS * i))
    }

    // Retry sequence: running → failed → retrying → done
    const retryStart = STEP_MS * (RETRY_IDX + 1)
    timers.push(setTimeout(() => setRetryState("failed"),   retryStart))
    timers.push(setTimeout(() => setRetryState("retrying"), retryStart + 700))
    timers.push(setTimeout(() => {
      setRetryState(null)
      setLineIdx(RETRY_IDX + 1)
    }, retryStart + 1500))

    // Steps after the retry step
    for (let i = RETRY_IDX + 2; i <= WORKFLOW_STEPS.length; i++) {
      timers.push(setTimeout(
        () => setLineIdx(i),
        retryStart + 1500 + STEP_MS * (i - RETRY_IDX - 1),
      ))
    }

    return () => timers.forEach(clearTimeout)
  }, [active, phase])

  return {
    phase,
    lineIdx,
    retryState,
    isActing:  phase === "acting",
    isResult:  phase === "result" || phase === "holding",
    isHolding: phase === "holding",
  }
}

