import { useEffect, useState } from "react"

/**
 * Members table: hover role → open dropdown → cursor picks Editor → Save.
 * `targetRole` stays User until Editor is chosen (no flick in the cell).
 * Cursor % are relative to the bordered table body.
 */

export type AccessPhase =
  | "setup"
  | "acting"
  | "result"
  | "holding"
  | "resetting"

const TIMING: Record<AccessPhase, number> = {
  setup: 500,
  acting: 3400,
  result: 320,
  holding: 2800,
  resetting: 320,
}

export type AccessTableStage =
  | "idle"
  | "roleHover"
  | "menuOpen"
  | "menuEditorHover"
  | "editorPicked"
  | "saveHover"
  | "saving"

/** Role options in the dropdown (top → bottom). */
export type MemberRole = "Admin" | "Editor" | "Publisher" | "User"

export const ROLE_MENU_OPTIONS: readonly MemberRole[] = [
  "Admin",
  "Editor",
  "Publisher",
  "User",
]

export const ACCESS_TABLE_CURSOR = {
  role: { x: 71, y: 50 },
  /** Editor row in the drop-up menu (second item — near top of drop-up). */
  menuEditor: { x: 72, y: 2 },
  save: { x: 91, y: 50 },
} as const

export function useAccessAnimation(active: boolean) {
  const [phase, setPhase] = useState<AccessPhase>("setup")
  const [stage, setStage] = useState<AccessTableStage>("idle")
  const [targetRole, setTargetRole] = useState<MemberRole>("User")
  const [pressed, setPressed] = useState(false)

  useEffect(() => {
    if (!active) return

    const next: Record<AccessPhase, AccessPhase> = {
      setup: "acting",
      acting: "result",
      result: "holding",
      holding: "resetting",
      resetting: "setup",
    }

    const t = setTimeout(() => setPhase(next[phase]), TIMING[phase])
    return () => clearTimeout(t)
  }, [active, phase])

  useEffect(() => {
    if (!active) return

    if (phase === "setup" || phase === "resetting") {
      setStage("idle")
      setTargetRole("User")
      setPressed(false)
      return
    }

    if (phase === "result" || phase === "holding") {
      setStage("idle")
      setPressed(false)
      return
    }

    if (phase !== "acting") return

    const timers: ReturnType<typeof setTimeout>[] = []

    setStage("roleHover")

    timers.push(setTimeout(() => setStage("menuOpen"), 480))
    timers.push(
      setTimeout(() => {
        setPressed(true)
      }, 520),
    )
    timers.push(setTimeout(() => setPressed(false), 620))

    timers.push(setTimeout(() => setStage("menuEditorHover"), 980))

    timers.push(
      setTimeout(() => {
        setStage("editorPicked")
        setTargetRole("Editor")
        setPressed(true)
      }, 1480),
    )
    timers.push(setTimeout(() => setPressed(false), 1600))

    timers.push(setTimeout(() => setStage("saveHover"), 1780))

    timers.push(
      setTimeout(() => {
        setStage("saving")
        setPressed(true)
      }, 2280),
    )
    timers.push(setTimeout(() => setPressed(false), 2420))

    return () => {
      timers.forEach(clearTimeout)
    }
  }, [active, phase])

  /** Menu visible; cell text stays User until `editorPicked` closes it. */
  const dropdownOpen =
    phase === "acting" &&
    (stage === "menuOpen" || stage === "menuEditorHover")

  const cursorVisible = phase === "acting" && stage !== "idle"

  const cursorAtSave = stage === "saveHover" || stage === "saving"
  const cursorAtMenuEditor =
    stage === "menuEditorHover" || stage === "editorPicked"

  const cursor = cursorAtSave
    ? ACCESS_TABLE_CURSOR.save
    : cursorAtMenuEditor
      ? ACCESS_TABLE_CURSOR.menuEditor
      : ACCESS_TABLE_CURSOR.role

  const rowHighlight =
    phase === "acting" &&
    stage !== "idle" &&
    stage !== "roleHover"

  const roleCellHot =
    phase === "acting" &&
    (stage === "roleHover" ||
      stage === "menuOpen" ||
      stage === "menuEditorHover")

  const saveHot =
    phase === "acting" && (stage === "saveHover" || stage === "saving")

  return {
    phase,
    stage,
    targetRole,
    dropdownOpen,
    cursor,
    cursorVisible,
    pressed,
    rowHighlight,
    roleCellHot,
    saveHot,
    isSaving: phase === "acting" && stage === "saving",
    isActing: phase === "acting",
    isResult: phase === "result" || phase === "holding",
    isHolding: phase === "holding",
  }
}

"use client"

import { useEffect, useState } from "react"

/**
 * Integrations animation — drives a `Connect an integration…` command palette for card 04.
 *
 * Story (one loop):
 *   setup      → palette open, empty list, cursor idle
 *   typing     → "supa" types into the search bar; no results yet
 *   appearing  → all 4 rows stagger in (realistic search-result reveal)
 *   hovering   → cursor walks GitHub → Vercel → Supabase
 *   connecting → Supabase row shows the purple `Connect` chip; cursor slides to the button and clicks
 *   holding    → resolved state holds
 *   resetting  → soft reset
 */

export type IntegrationsPhase =
  | "setup"
  | "typing"
  | "appearing"
  | "hovering"
  | "connecting"
  | "loading"
  | "resetting"

const TIMING: Record<IntegrationsPhase, number> = {
  setup: 500,
  typing: 1100,
  appearing: 700,
  hovering: 1300,
  connecting: 600,
  loading: 2200,
  resetting: 300,
}

const PHASE_NEXT: Record<IntegrationsPhase, IntegrationsPhase> = {
  setup: "typing",
  typing: "appearing",
  appearing: "hovering",
  hovering: "connecting",
  connecting: "loading",
  loading: "resetting",
  resetting: "setup",
}

export type Integration = {
  id: "github" | "vercel" | "supabase" | "openai"
  name: string
  kind: string
}

/** Row order matches vertical layout — cursor percentages target each row's center */
export const INTEGRATIONS: readonly Integration[] = [
  { id: "github", name: "GitHub", kind: "Code" },
  { id: "vercel", name: "Vercel", kind: "Deploy" },
  { id: "supabase", name: "Supabase", kind: "Database" },
  { id: "openai", name: "OpenAI", kind: "AI" },
]

/** The target row the cursor lands on — animating in on it creates the story */
export const INTEGRATIONS_TARGET_IDX = 2

export const INTEGRATIONS_QUERY = "supa"

export function useIntegrationsAnimation(active: boolean) {
  const [phase, setPhase] = useState<IntegrationsPhase>("setup")
  const [hoverIdx, setHoverIdx] = useState(-1)
  const [typed, setTyped] = useState(0)
  const [pressed, setPressed] = useState(false)
  const [visibleCount, setVisibleCount] = useState(0)

  // Phase timer
  useEffect(() => {
    if (!active) {
      setPhase("setup")
      return
    }
    const t = setTimeout(() => setPhase(PHASE_NEXT[phase]), TIMING[phase])
    return () => clearTimeout(t)
  }, [active, phase])

  // Phase → derived state
  useEffect(() => {
    if (!active) return

    if (phase === "setup" || phase === "resetting") {
      setHoverIdx(-1)
      setTyped(0)
      setPressed(false)
      setVisibleCount(0)
      return
    }

    if (phase === "typing") {
      setHoverIdx(-1)
      setVisibleCount(0)
      setTyped(0)
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= INTEGRATIONS_QUERY.length; i++) {
        timers.push(setTimeout(() => setTyped(i), 200 + i * 210))
      }
      return () => timers.forEach(clearTimeout)
    }

    if (phase === "appearing") {
      setHoverIdx(-1)
      setTyped(INTEGRATIONS_QUERY.length)
      setVisibleCount(0)
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 0; i < INTEGRATIONS.length; i++) {
        timers.push(setTimeout(() => setVisibleCount(i + 1), 60 + i * 150))
      }
      return () => timers.forEach(clearTimeout)
    }

    if (phase === "hovering") {
      setVisibleCount(INTEGRATIONS.length)
      setPressed(false)
      // Walk GitHub → Vercel → Supabase
      const stops = [0, 1, INTEGRATIONS_TARGET_IDX]
      const stepMs = 320
      const timers: ReturnType<typeof setTimeout>[] = []
      stops.forEach((s, i) => {
        timers.push(setTimeout(() => setHoverIdx(s), i * stepMs))
      })
      return () => timers.forEach(clearTimeout)
    }

    if (phase === "connecting") {
      // Connect chip appears; cursor slides to button and clicks
      setHoverIdx(INTEGRATIONS_TARGET_IDX)
      setVisibleCount(INTEGRATIONS.length)
      const timers: ReturnType<typeof setTimeout>[] = [
        setTimeout(() => setPressed(true), 350),
        setTimeout(() => setPressed(false), 500),
      ]
      return () => timers.forEach(clearTimeout)
    }

    if (phase === "loading") {
      setHoverIdx(INTEGRATIONS_TARGET_IDX)
      setVisibleCount(INTEGRATIONS.length)
      setPressed(false)
    }
  }, [active, phase])

  return {
    phase,
    hoverIdx,
    typed,
    pressed,
    visibleCount,
    query: INTEGRATIONS_QUERY.slice(0, typed),
    isResult: phase === "connecting" || phase === "loading",
    cursorOnConnect: phase === "connecting" || phase === "loading",
    isLoading: phase === "loading",
  }
}

